import { storageService } from '../storage.service';

/** The two columns of a report row that can locate its PDF. */
export interface ReportObjectRef {
  storageKey?: string | null;
  s3Url?: string | null;
}

/**
 * Object key of a report's PDF in the ACTIVE store, or null when the report has none.
 *
 * Reports generated by this backend carry `storageKey`. Reports migrated from the website carry
 * only `s3Url`, the website's public URL of the PDF (`https://<bucket>.s3.<region>.amazonaws.com/
 * assets/<ts>-report-<id>.pdf`). That URL is turned into a key with `storageService.resolveKey`,
 * which accepts only the configured bucket, the buckets listed in STORAGE_LEGACY_AWS_BUCKETS
 * (copied into the active store under the same key) and the local development route. Any other
 * host gives null: the URL is never fetched, so a stored reference cannot make the API read from
 * an arbitrary address. The object is always read from the configured store.
 */
export function reportObjectKey(report: ReportObjectRef | null | undefined): string | null {
  if (!report) return null;
  if (report.storageKey) return report.storageKey;
  return storageService.resolveKey(report.s3Url);
}
